CREATE TABLE IF NOT EXISTS "depots" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Short site code printed on labels and used in route names, e.g. LDN-E.
	"code" VARCHAR(16) NOT NULL UNIQUE,
	-- Site name.
	"name" VARCHAR(120) NOT NULL,
	-- Street address, needed for the return leg and for agency drivers finding the yard.
	"address_line1" VARCHAR(200),
	-- City or locality.
	"city" VARCHAR(120),
	-- WGS84 latitude of the yard gate. Every route starts and usually ends here, so it anchors all distance estimates.
	"latitude" NUMERIC(9,6) NOT NULL,
	-- WGS84 longitude.
	"longitude" NUMERIC(9,6) NOT NULL,
	-- IANA zone. Route dates and cut-offs are local facts; every timestamp in the schema is an instant. Mixing the two is what makes a route appear on the wrong day.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Local time after which orders roll to the next route date. The single most consulted number in the building.
	"dispatch_cutoff_time" TIME,
	-- Number of bays, which caps how many routes can be loaded in parallel and therefore how early the last van leaves.
	"loading_bays" SMALLINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "depots" IS 'A physical dispatch site. Everything is scoped to a depot because capacity, cut-offs and driver pools do not transfer between them.';
COMMENT ON COLUMN "depots"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "depots"."code" IS 'Short site code printed on labels and used in route names, e.g. LDN-E.';
COMMENT ON COLUMN "depots"."name" IS 'Site name.';
COMMENT ON COLUMN "depots"."address_line1" IS 'Street address, needed for the return leg and for agency drivers finding the yard.';
COMMENT ON COLUMN "depots"."city" IS 'City or locality.';
COMMENT ON COLUMN "depots"."latitude" IS 'WGS84 latitude of the yard gate. Every route starts and usually ends here, so it anchors all distance estimates.';
COMMENT ON COLUMN "depots"."longitude" IS 'WGS84 longitude.';
COMMENT ON COLUMN "depots"."timezone" IS 'IANA zone. Route dates and cut-offs are local facts; every timestamp in the schema is an instant. Mixing the two is what makes a route appear on the wrong day.';
COMMENT ON COLUMN "depots"."dispatch_cutoff_time" IS 'Local time after which orders roll to the next route date. The single most consulted number in the building.';
COMMENT ON COLUMN "depots"."loading_bays" IS 'Number of bays, which caps how many routes can be loaded in parallel and therefore how early the last van leaves.';

CREATE TABLE IF NOT EXISTS "drivers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Depot the driver normally works from, used for default rostering.
	"home_depot_id" BIGINT NOT NULL,
	-- Identifier on the handheld device and in the payroll feed.
	"driver_code" VARCHAR(32) NOT NULL UNIQUE,
	-- Name shown to the customer in tracking notifications.
	"full_name" VARCHAR(160) NOT NULL,
	-- Mobile number, used for dispatch contact and for the customer callback on a failed delivery.
	"phone" VARCHAR(32),
	-- employee | agency | contractor. Decides which working-time rules apply to the shift, which the route planner must respect.
	"employment_type" VARCHAR(16) NOT NULL DEFAULT 'employee',
	-- Highest vehicle category the driver may operate, checked against the vehicle before dispatch.
	"licence_class" VARCHAR(16),
	-- active | inactive | suspended. Only active drivers are offered to the planner.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "drivers" IS 'A person who runs routes. Thin by design: the constraints that matter to planning live on the shift, not on the person.';
COMMENT ON COLUMN "drivers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "drivers"."home_depot_id" IS 'Depot the driver normally works from, used for default rostering.';
COMMENT ON COLUMN "drivers"."driver_code" IS 'Identifier on the handheld device and in the payroll feed.';
COMMENT ON COLUMN "drivers"."full_name" IS 'Name shown to the customer in tracking notifications.';
COMMENT ON COLUMN "drivers"."phone" IS 'Mobile number, used for dispatch contact and for the customer callback on a failed delivery.';
COMMENT ON COLUMN "drivers"."employment_type" IS 'employee | agency | contractor. Decides which working-time rules apply to the shift, which the route planner must respect.';
COMMENT ON COLUMN "drivers"."licence_class" IS 'Highest vehicle category the driver may operate, checked against the vehicle before dispatch.';
COMMENT ON COLUMN "drivers"."status" IS 'active | inactive | suspended. Only active drivers are offered to the planner.';

CREATE INDEX "idx_drivers_depot_status"
ON "drivers" ("home_depot_id", "status");

CREATE TABLE IF NOT EXISTS "vehicles" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Depot the vehicle is based at.
	"home_depot_id" BIGINT NOT NULL,
	-- Plate, which is how the yard, the customer and the parking authority all identify it.
	"registration_plate" VARCHAR(16) NOT NULL UNIQUE,
	-- bike | cargo_bike | car | van | box_truck. Type decides access restrictions as much as capacity — a box truck cannot serve a low-bridge estate.
	"vehicle_type" VARCHAR(24) NOT NULL DEFAULT 'van',
	-- Payload capacity. One half of the bin-packing constraint the planner solves.
	"max_weight_kg" NUMERIC(10,2) NOT NULL,
	-- Load volume. The binding constraint far more often than weight for parcel work.
	"max_volume_cbm" NUMERIC(10,3) NOT NULL,
	-- Practical stop ceiling for one shift, which is a sortation and handling limit rather than a physical one.
	"max_stops" SMALLINT,
	-- True when heavy items can be handled solo. An order needing one must not be planned onto a van without one.
	"has_tail_lift" BOOLEAN NOT NULL DEFAULT false,
	-- True for chilled and frozen work, which restricts which orders may share the vehicle.
	"is_temperature_controlled" BOOLEAN NOT NULL DEFAULT false,
	-- available | in_use | maintenance | retired. Maintenance takes it out of planning without deleting its route history.
	"status" VARCHAR(16) NOT NULL DEFAULT 'available',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "vehicles" IS 'The moving container and its constraints. Only the attributes a planner needs are here; maintenance, telematics and fuel are a fleet problem, modelled in the fleet management example.';
COMMENT ON COLUMN "vehicles"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "vehicles"."home_depot_id" IS 'Depot the vehicle is based at.';
COMMENT ON COLUMN "vehicles"."registration_plate" IS 'Plate, which is how the yard, the customer and the parking authority all identify it.';
COMMENT ON COLUMN "vehicles"."vehicle_type" IS 'bike | cargo_bike | car | van | box_truck. Type decides access restrictions as much as capacity — a box truck cannot serve a low-bridge estate.';
COMMENT ON COLUMN "vehicles"."max_weight_kg" IS 'Payload capacity. One half of the bin-packing constraint the planner solves.';
COMMENT ON COLUMN "vehicles"."max_volume_cbm" IS 'Load volume. The binding constraint far more often than weight for parcel work.';
COMMENT ON COLUMN "vehicles"."max_stops" IS 'Practical stop ceiling for one shift, which is a sortation and handling limit rather than a physical one.';
COMMENT ON COLUMN "vehicles"."has_tail_lift" IS 'True when heavy items can be handled solo. An order needing one must not be planned onto a van without one.';
COMMENT ON COLUMN "vehicles"."is_temperature_controlled" IS 'True for chilled and frozen work, which restricts which orders may share the vehicle.';
COMMENT ON COLUMN "vehicles"."status" IS 'available | in_use | maintenance | retired. Maintenance takes it out of planning without deleting its route history.';

CREATE INDEX "idx_vehicles_depot_status"
ON "vehicles" ("home_depot_id", "status");

CREATE TABLE IF NOT EXISTS "driver_shifts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Driver rostered.
	"driver_id" BIGINT NOT NULL,
	-- Depot worked from that day, which is not always the home depot.
	"depot_id" BIGINT NOT NULL,
	-- Local calendar date of the shift. A date, not a timestamp, because a night shift crossing midnight still belongs to one operating day.
	"shift_date" DATE NOT NULL,
	-- Rostered start instant.
	"planned_start_at" TIMESTAMPTZ NOT NULL,
	-- Rostered end. The planner will not build a route it cannot finish inside this.
	"planned_end_at" TIMESTAMPTZ NOT NULL,
	-- Clock-in. The gap from planned is the leading indicator of a late final delivery.
	"actual_start_at" TIMESTAMPTZ,
	-- Clock-out.
	"actual_end_at" TIMESTAMPTZ,
	-- Mandated break time, which the planner must reserve or the route is illegal before it starts.
	"break_minutes" SMALLINT NOT NULL DEFAULT 0,
	-- Legal or contractual driving ceiling for this shift. A hard constraint, not a target.
	"max_driving_minutes" SMALLINT,
	-- planned | started | completed | cancelled | no_show. No-show is its own state because it triggers a same-morning replan, not a reassignment.
	"status" VARCHAR(16) NOT NULL DEFAULT 'planned',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "driver_shifts" IS 'Driver availability as the planner sees it. Working-time limits belong here rather than on the driver, because they change per shift and are what make a plan feasible or fiction.';
COMMENT ON COLUMN "driver_shifts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "driver_shifts"."driver_id" IS 'Driver rostered.';
COMMENT ON COLUMN "driver_shifts"."depot_id" IS 'Depot worked from that day, which is not always the home depot.';
COMMENT ON COLUMN "driver_shifts"."shift_date" IS 'Local calendar date of the shift. A date, not a timestamp, because a night shift crossing midnight still belongs to one operating day.';
COMMENT ON COLUMN "driver_shifts"."planned_start_at" IS 'Rostered start instant.';
COMMENT ON COLUMN "driver_shifts"."planned_end_at" IS 'Rostered end. The planner will not build a route it cannot finish inside this.';
COMMENT ON COLUMN "driver_shifts"."actual_start_at" IS 'Clock-in. The gap from planned is the leading indicator of a late final delivery.';
COMMENT ON COLUMN "driver_shifts"."actual_end_at" IS 'Clock-out.';
COMMENT ON COLUMN "driver_shifts"."break_minutes" IS 'Mandated break time, which the planner must reserve or the route is illegal before it starts.';
COMMENT ON COLUMN "driver_shifts"."max_driving_minutes" IS 'Legal or contractual driving ceiling for this shift. A hard constraint, not a target.';
COMMENT ON COLUMN "driver_shifts"."status" IS 'planned | started | completed | cancelled | no_show. No-show is its own state because it triggers a same-morning replan, not a reassignment.';

CREATE UNIQUE INDEX "uq_shifts_driver_date"
ON "driver_shifts" ("driver_id", "shift_date");
CREATE INDEX "idx_shifts_depot_date"
ON "driver_shifts" ("depot_id", "shift_date");

CREATE TABLE IF NOT EXISTS "delivery_orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Depot responsible for delivering it, assigned at sortation.
	"depot_id" BIGINT NOT NULL,
	-- Order or consignment id from the upstream system. The only identifier the customer and the merchant recognise.
	"external_reference" VARCHAR(64) NOT NULL UNIQUE,
	-- Who should receive it, shown to the driver and checked on an age-restricted handover.
	"recipient_name" VARCHAR(160) NOT NULL,
	-- Contact number for the courier call that saves a failed attempt.
	"recipient_phone" VARCHAR(32),
	-- Street address as given. Kept verbatim alongside the geocode because a wrong geocode with a right address is recoverable and the reverse is not.
	"address_line1" VARCHAR(200) NOT NULL,
	-- Postal code, the strongest single input to both geocoding and route clustering.
	"postcode" VARCHAR(16),
	-- Geocoded WGS84 latitude. Null when the address failed to geocode, which is a work queue rather than an error.
	"latitude" NUMERIC(9,6),
	-- Geocoded WGS84 longitude.
	"longitude" NUMERIC(9,6),
	-- Earliest promised arrival. Null means all-day service, which is a materially cheaper product.
	"window_start_at" TIMESTAMPTZ,
	-- Latest promised arrival. The constraint that turns routing from a travelling salesman problem into a scheduling one.
	"window_end_at" TIMESTAMPTZ,
	-- Expected time on the doorstep. Ignoring it is why optimistic plans run an hour late by mid-afternoon — a hundred stops at two minutes each is over three hours of standing still.
	"service_seconds" SMALLINT NOT NULL DEFAULT 120,
	-- Parcel weight, checked against vehicle payload when loading a route.
	"weight_kg" NUMERIC(8,2) NOT NULL DEFAULT 0,
	-- Parcel volume, usually the binding capacity constraint.
	"volume_cbm" NUMERIC(8,4) NOT NULL DEFAULT 0,
	-- True when a name must be captured. Changes what counts as a valid proof of delivery.
	"requires_signature" BOOLEAN NOT NULL DEFAULT false,
	-- True for restricted goods. A failed age check is a legitimate delivery failure, not a driver error.
	"requires_age_check" BOOLEAN NOT NULL DEFAULT false,
	-- Higher goes first when not everything fits. Used for premium service and for parcels already failed once.
	"priority" SMALLINT NOT NULL DEFAULT 0,
	-- pending | planned | out_for_delivery | delivered | failed | returned | cancelled. failed is a resting state that the next day replan picks up from.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "delivery_orders" IS 'A parcel to be delivered, independent of any route. It survives being planned, failed and replanned onto a different route tomorrow, which is why its status is not a property of the stop.';
COMMENT ON COLUMN "delivery_orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "delivery_orders"."depot_id" IS 'Depot responsible for delivering it, assigned at sortation.';
COMMENT ON COLUMN "delivery_orders"."external_reference" IS 'Order or consignment id from the upstream system. The only identifier the customer and the merchant recognise.';
COMMENT ON COLUMN "delivery_orders"."recipient_name" IS 'Who should receive it, shown to the driver and checked on an age-restricted handover.';
COMMENT ON COLUMN "delivery_orders"."recipient_phone" IS 'Contact number for the courier call that saves a failed attempt.';
COMMENT ON COLUMN "delivery_orders"."address_line1" IS 'Street address as given. Kept verbatim alongside the geocode because a wrong geocode with a right address is recoverable and the reverse is not.';
COMMENT ON COLUMN "delivery_orders"."postcode" IS 'Postal code, the strongest single input to both geocoding and route clustering.';
COMMENT ON COLUMN "delivery_orders"."latitude" IS 'Geocoded WGS84 latitude. Null when the address failed to geocode, which is a work queue rather than an error.';
COMMENT ON COLUMN "delivery_orders"."longitude" IS 'Geocoded WGS84 longitude.';
COMMENT ON COLUMN "delivery_orders"."window_start_at" IS 'Earliest promised arrival. Null means all-day service, which is a materially cheaper product.';
COMMENT ON COLUMN "delivery_orders"."window_end_at" IS 'Latest promised arrival. The constraint that turns routing from a travelling salesman problem into a scheduling one.';
COMMENT ON COLUMN "delivery_orders"."service_seconds" IS 'Expected time on the doorstep. Ignoring it is why optimistic plans run an hour late by mid-afternoon — a hundred stops at two minutes each is over three hours of standing still.';
COMMENT ON COLUMN "delivery_orders"."weight_kg" IS 'Parcel weight, checked against vehicle payload when loading a route.';
COMMENT ON COLUMN "delivery_orders"."volume_cbm" IS 'Parcel volume, usually the binding capacity constraint.';
COMMENT ON COLUMN "delivery_orders"."requires_signature" IS 'True when a name must be captured. Changes what counts as a valid proof of delivery.';
COMMENT ON COLUMN "delivery_orders"."requires_age_check" IS 'True for restricted goods. A failed age check is a legitimate delivery failure, not a driver error.';
COMMENT ON COLUMN "delivery_orders"."priority" IS 'Higher goes first when not everything fits. Used for premium service and for parcels already failed once.';
COMMENT ON COLUMN "delivery_orders"."status" IS 'pending | planned | out_for_delivery | delivered | failed | returned | cancelled. failed is a resting state that the next day replan picks up from.';

CREATE INDEX "idx_orders_depot_status"
ON "delivery_orders" ("depot_id", "status");
CREATE INDEX "idx_orders_window_end"
ON "delivery_orders" ("window_end_at");

CREATE TABLE IF NOT EXISTS "routes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Depot the route runs from.
	"depot_id" BIGINT NOT NULL,
	-- Operating day in depot-local terms. Dates and instants are kept distinct throughout; this one is a date because a route belongs to a day, not to an hour.
	"route_date" DATE NOT NULL,
	-- Name on the loading bay and on the manifest, e.g. E-14. Unique within a depot and a date, reused every week.
	"route_code" VARCHAR(32) NOT NULL,
	-- Vehicle assigned. Null while the route is still being planned.
	"vehicle_id" BIGINT,
	-- Shift running it. Null until dispatch, and a no-show replaces it without rebuilding the stop list.
	"driver_shift_id" BIGINT,
	-- planned | dispatched | in_progress | completed | cancelled. in_progress is what makes a route visible on the live map and immune to wholesale replanning.
	"status" VARCHAR(24) NOT NULL DEFAULT 'planned',
	-- Incremented on every re-sequence. The stops carry the sequence; this is how you tell which plan a driver was actually handed.
	"plan_version" INTEGER NOT NULL DEFAULT 1,
	-- Planned departure from the depot.
	"planned_start_at" TIMESTAMPTZ,
	-- Actual departure, taken from the depot geofence exit rather than from a button press.
	"actual_start_at" TIMESTAMPTZ,
	-- Return to the depot.
	"actual_end_at" TIMESTAMPTZ,
	-- Stops in the plan as dispatched, frozen so completion rate is measured against what was promised rather than against what survived.
	"planned_stop_count" SMALLINT NOT NULL DEFAULT 0,
	-- Distance the optimiser projected.
	"planned_distance_km" NUMERIC(9,2),
	-- Distance actually covered. The difference from the plan is the honest measure of how good the optimiser was, and it is only available because both are stored.
	"actual_distance_km" NUMERIC(9,2),
	-- Duration the optimiser projected, including service time.
	"planned_duration_minutes" INTEGER,
	-- Duration actually taken.
	"actual_duration_minutes" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "routes" IS 'One vehicle, one driver, one day. Planned and actual measures sit side by side on purpose: a route is a forecast that is then executed, and keeping only the outcome destroys the ability to improve the forecast.';
COMMENT ON COLUMN "routes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "routes"."depot_id" IS 'Depot the route runs from.';
COMMENT ON COLUMN "routes"."route_date" IS 'Operating day in depot-local terms. Dates and instants are kept distinct throughout; this one is a date because a route belongs to a day, not to an hour.';
COMMENT ON COLUMN "routes"."route_code" IS 'Name on the loading bay and on the manifest, e.g. E-14. Unique within a depot and a date, reused every week.';
COMMENT ON COLUMN "routes"."vehicle_id" IS 'Vehicle assigned. Null while the route is still being planned.';
COMMENT ON COLUMN "routes"."driver_shift_id" IS 'Shift running it. Null until dispatch, and a no-show replaces it without rebuilding the stop list.';
COMMENT ON COLUMN "routes"."status" IS 'planned | dispatched | in_progress | completed | cancelled. in_progress is what makes a route visible on the live map and immune to wholesale replanning.';
COMMENT ON COLUMN "routes"."plan_version" IS 'Incremented on every re-sequence. The stops carry the sequence; this is how you tell which plan a driver was actually handed.';
COMMENT ON COLUMN "routes"."planned_start_at" IS 'Planned departure from the depot.';
COMMENT ON COLUMN "routes"."actual_start_at" IS 'Actual departure, taken from the depot geofence exit rather than from a button press.';
COMMENT ON COLUMN "routes"."actual_end_at" IS 'Return to the depot.';
COMMENT ON COLUMN "routes"."planned_stop_count" IS 'Stops in the plan as dispatched, frozen so completion rate is measured against what was promised rather than against what survived.';
COMMENT ON COLUMN "routes"."planned_distance_km" IS 'Distance the optimiser projected.';
COMMENT ON COLUMN "routes"."actual_distance_km" IS 'Distance actually covered. The difference from the plan is the honest measure of how good the optimiser was, and it is only available because both are stored.';
COMMENT ON COLUMN "routes"."planned_duration_minutes" IS 'Duration the optimiser projected, including service time.';
COMMENT ON COLUMN "routes"."actual_duration_minutes" IS 'Duration actually taken.';

CREATE UNIQUE INDEX "uq_routes_depot_date_code"
ON "routes" ("depot_id", "route_date", "route_code");
CREATE INDEX "idx_routes_date_status"
ON "routes" ("route_date", "status");

CREATE TABLE IF NOT EXISTS "route_stops" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Route the stop belongs to.
	"route_id" BIGINT NOT NULL,
	-- Position in the plan as dispatched. Frozen at dispatch; a re-sequence writes a new revision rather than overwriting it.
	"planned_sequence" SMALLINT NOT NULL,
	-- Position the stop was actually served in. Null until served. When it differs from planned, the driver knew something the optimiser did not — and that difference is the training data.
	"actual_sequence" SMALLINT,
	-- delivery | pickup | break | depot_return. Breaks and the return leg are stops because they consume time and must be sequenced, not assumed.
	"stop_type" VARCHAR(16) NOT NULL DEFAULT 'delivery',
	-- Address snapshot at planning time, so a later address correction on the order cannot rewrite where the van was sent.
	"address_line1" VARCHAR(200),
	-- WGS84 latitude used for sequencing and for the arrival geofence.
	"latitude" NUMERIC(9,6),
	-- WGS84 longitude.
	"longitude" NUMERIC(9,6),
	-- Radius that counts as arrival here. Per stop, because a city doorstep needs thirty metres and a rural farm gate needs three hundred.
	"geofence_radius_m" SMALLINT NOT NULL DEFAULT 75,
	-- ETA from the optimiser, and the basis of the notification sent to the customer.
	"planned_arrival_at" TIMESTAMPTZ,
	-- Detected arrival, normally from the geofence. Recorded separately from the attempt because arriving and delivering are different events.
	"actual_arrival_at" TIMESTAMPTZ,
	-- Detected departure. The gap from arrival is real service time, which is what corrects the estimates used for planning.
	"actual_departure_at" TIMESTAMPTZ,
	-- pending | arrived | completed | failed | skipped. Skipped is not failed: it means the driver bypassed it, usually to be resequenced in later.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "route_stops" IS 'A place the van is expected to be, in an order. Stops are addresses, not parcels: three orders for the same block are one stop, which is why quantities and outcomes hang off the link table and the attempts, not off here.';
COMMENT ON COLUMN "route_stops"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "route_stops"."route_id" IS 'Route the stop belongs to.';
COMMENT ON COLUMN "route_stops"."planned_sequence" IS 'Position in the plan as dispatched. Frozen at dispatch; a re-sequence writes a new revision rather than overwriting it.';
COMMENT ON COLUMN "route_stops"."actual_sequence" IS 'Position the stop was actually served in. Null until served. When it differs from planned, the driver knew something the optimiser did not — and that difference is the training data.';
COMMENT ON COLUMN "route_stops"."stop_type" IS 'delivery | pickup | break | depot_return. Breaks and the return leg are stops because they consume time and must be sequenced, not assumed.';
COMMENT ON COLUMN "route_stops"."address_line1" IS 'Address snapshot at planning time, so a later address correction on the order cannot rewrite where the van was sent.';
COMMENT ON COLUMN "route_stops"."latitude" IS 'WGS84 latitude used for sequencing and for the arrival geofence.';
COMMENT ON COLUMN "route_stops"."longitude" IS 'WGS84 longitude.';
COMMENT ON COLUMN "route_stops"."geofence_radius_m" IS 'Radius that counts as arrival here. Per stop, because a city doorstep needs thirty metres and a rural farm gate needs three hundred.';
COMMENT ON COLUMN "route_stops"."planned_arrival_at" IS 'ETA from the optimiser, and the basis of the notification sent to the customer.';
COMMENT ON COLUMN "route_stops"."actual_arrival_at" IS 'Detected arrival, normally from the geofence. Recorded separately from the attempt because arriving and delivering are different events.';
COMMENT ON COLUMN "route_stops"."actual_departure_at" IS 'Detected departure. The gap from arrival is real service time, which is what corrects the estimates used for planning.';
COMMENT ON COLUMN "route_stops"."status" IS 'pending | arrived | completed | failed | skipped. Skipped is not failed: it means the driver bypassed it, usually to be resequenced in later.';

CREATE UNIQUE INDEX "uq_stops_route_planned_sequence"
ON "route_stops" ("route_id", "planned_sequence");
CREATE INDEX "idx_stops_route_actual_sequence"
ON "route_stops" ("route_id", "actual_sequence");
CREATE INDEX "idx_stops_status"
ON "route_stops" ("status");

CREATE TABLE IF NOT EXISTS "stop_parcels" (
	-- Stop where this parcel is handed over. Half of the composite key.
	"route_stop_id" BIGINT,
	-- Parcel being delivered at that stop. Half of the composite key, so one stop can carry several parcels and one parcel can appear at a later stop after a failed attempt.
	"delivery_order_id" BIGINT,
	-- Where it sits in the van — shelf, cage, tote id. Saves the driver the two minutes that make a hundred-stop route infeasible.
	"load_position" VARCHAR(24),
	-- When this parcel was attached to this stop, which distinguishes the original load from something added during a mid-route re-sequence.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("route_stop_id", "delivery_order_id")
);

COMMENT ON TABLE "stop_parcels" IS 'The many-to-many between stops and parcels. It exists because the planner optimises over addresses while the business tracks parcels, and collapsing the two makes a three-parcel household look like three drive-ups.';
COMMENT ON COLUMN "stop_parcels"."route_stop_id" IS 'Stop where this parcel is handed over. Half of the composite key.';
COMMENT ON COLUMN "stop_parcels"."delivery_order_id" IS 'Parcel being delivered at that stop. Half of the composite key, so one stop can carry several parcels and one parcel can appear at a later stop after a failed attempt.';
COMMENT ON COLUMN "stop_parcels"."load_position" IS 'Where it sits in the van — shelf, cage, tote id. Saves the driver the two minutes that make a hundred-stop route infeasible.';
COMMENT ON COLUMN "stop_parcels"."added_at" IS 'When this parcel was attached to this stop, which distinguishes the original load from something added during a mid-route re-sequence.';

CREATE INDEX "idx_stop_parcels_order"
ON "stop_parcels" ("delivery_order_id");

CREATE TABLE IF NOT EXISTS "route_revisions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Route that was re-planned.
	"route_id" BIGINT NOT NULL,
	-- Monotonic counter matching routes.plan_version after the change was applied.
	"revision_number" INTEGER NOT NULL,
	-- When the new sequence took effect on the handheld.
	"revised_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- optimiser | dispatcher | driver. Who changed it matters: a driver reordering by local knowledge and a dispatcher inserting an urgent job are different signals.
	"revised_by" VARCHAR(24) NOT NULL DEFAULT 'optimiser',
	-- traffic | failed_attempt | new_order | vehicle_breakdown | customer_reschedule | driver_preference. The reason is what makes re-sequencing analysable instead of just noisy.
	"reason" VARCHAR(32) NOT NULL,
	-- The ordered stop ids as of this revision. A document rather than rows, because it is written once, read whole during an investigation, and never joined to.
	"sequence_snapshot" JSONB NOT NULL,
	-- Stops still outstanding when the change was made, the context that decides whether the change was cheap or expensive.
	"stops_remaining" SMALLINT,
	-- Projected distance change, positive or negative. Summed over a day it is the running cost of dynamic dispatch.
	"distance_delta_km" NUMERIC(9,2),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "route_revisions" IS 'The history of how a plan changed during the day. Without it the only surviving artefact is the final order, and the question that actually matters — did re-sequencing help — becomes unanswerable.';
COMMENT ON COLUMN "route_revisions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "route_revisions"."route_id" IS 'Route that was re-planned.';
COMMENT ON COLUMN "route_revisions"."revision_number" IS 'Monotonic counter matching routes.plan_version after the change was applied.';
COMMENT ON COLUMN "route_revisions"."revised_at" IS 'When the new sequence took effect on the handheld.';
COMMENT ON COLUMN "route_revisions"."revised_by" IS 'optimiser | dispatcher | driver. Who changed it matters: a driver reordering by local knowledge and a dispatcher inserting an urgent job are different signals.';
COMMENT ON COLUMN "route_revisions"."reason" IS 'traffic | failed_attempt | new_order | vehicle_breakdown | customer_reschedule | driver_preference. The reason is what makes re-sequencing analysable instead of just noisy.';
COMMENT ON COLUMN "route_revisions"."sequence_snapshot" IS 'The ordered stop ids as of this revision. A document rather than rows, because it is written once, read whole during an investigation, and never joined to.';
COMMENT ON COLUMN "route_revisions"."stops_remaining" IS 'Stops still outstanding when the change was made, the context that decides whether the change was cheap or expensive.';
COMMENT ON COLUMN "route_revisions"."distance_delta_km" IS 'Projected distance change, positive or negative. Summed over a day it is the running cost of dynamic dispatch.';

CREATE UNIQUE INDEX "uq_revisions_route_number"
ON "route_revisions" ("route_id", "revision_number");

CREATE TABLE IF NOT EXISTS "delivery_attempts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stop at which the attempt was made.
	"route_stop_id" BIGINT NOT NULL,
	-- Parcel being attempted. Per parcel, not per stop, because one stop can deliver two of three parcels successfully.
	"delivery_order_id" BIGINT NOT NULL,
	-- Which attempt this is for the parcel across all routes and days. Carriers price and abandon on this number.
	"attempt_number" SMALLINT NOT NULL DEFAULT 1,
	-- When the driver recorded the outcome, which can be minutes after the doorstep on a poor connection.
	"attempted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- delivered | customer_absent | no_access | refused | address_not_found | unsafe_location | age_check_failed | damaged. Distinguishing absent from no_access matters: one is retried tomorrow, the other needs a different plan entirely.
	"outcome" VARCHAR(24) NOT NULL,
	-- What the driver typed or selected beyond the code, which is what a customer-service agent reads first.
	"failure_notes" TEXT,
	-- retry_tomorrow | retry_with_neighbour | hold_at_depot | return_to_sender. Decided at the doorstep and consumed by the next planning run; null for a successful delivery.
	"next_action" VARCHAR(24),
	-- Where the device was when the outcome was recorded, which is how a delivery marked complete from three streets away gets found.
	"latitude" NUMERIC(9,6),
	-- WGS84 longitude at the time of the attempt.
	"longitude" NUMERIC(9,6),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "delivery_attempts" IS 'One row per parcel per doorstep event, successful or not. Failed attempts are the expensive half of last-mile economics, so they are first-class rows rather than a status the next attempt overwrites.';
COMMENT ON COLUMN "delivery_attempts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "delivery_attempts"."route_stop_id" IS 'Stop at which the attempt was made.';
COMMENT ON COLUMN "delivery_attempts"."delivery_order_id" IS 'Parcel being attempted. Per parcel, not per stop, because one stop can deliver two of three parcels successfully.';
COMMENT ON COLUMN "delivery_attempts"."attempt_number" IS 'Which attempt this is for the parcel across all routes and days. Carriers price and abandon on this number.';
COMMENT ON COLUMN "delivery_attempts"."attempted_at" IS 'When the driver recorded the outcome, which can be minutes after the doorstep on a poor connection.';
COMMENT ON COLUMN "delivery_attempts"."outcome" IS 'delivered | customer_absent | no_access | refused | address_not_found | unsafe_location | age_check_failed | damaged. Distinguishing absent from no_access matters: one is retried tomorrow, the other needs a different plan entirely.';
COMMENT ON COLUMN "delivery_attempts"."failure_notes" IS 'What the driver typed or selected beyond the code, which is what a customer-service agent reads first.';
COMMENT ON COLUMN "delivery_attempts"."next_action" IS 'retry_tomorrow | retry_with_neighbour | hold_at_depot | return_to_sender. Decided at the doorstep and consumed by the next planning run; null for a successful delivery.';
COMMENT ON COLUMN "delivery_attempts"."latitude" IS 'Where the device was when the outcome was recorded, which is how a delivery marked complete from three streets away gets found.';
COMMENT ON COLUMN "delivery_attempts"."longitude" IS 'WGS84 longitude at the time of the attempt.';

CREATE UNIQUE INDEX "uq_attempts_order_number"
ON "delivery_attempts" ("delivery_order_id", "attempt_number");
CREATE INDEX "idx_attempts_stop"
ON "delivery_attempts" ("route_stop_id");
CREATE INDEX "idx_attempts_outcome"
ON "delivery_attempts" ("outcome");

CREATE TABLE IF NOT EXISTS "proofs_of_delivery" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Attempt this proves. Unique, so proof is one-to-one with a successful attempt and cannot be attached retrospectively to a different one.
	"delivery_attempt_id" BIGINT NOT NULL UNIQUE,
	-- signature | photo | pin | id_check | safe_place. The type must satisfy what the order demanded, which is why requires_signature lives on the order.
	"proof_type" VARCHAR(16) NOT NULL DEFAULT 'photo',
	-- Device timestamp of capture, not upload. Handhelds capture offline and sync later, sometimes hours later.
	"captured_at" TIMESTAMPTZ NOT NULL,
	-- Name given at handover. Null for a contactless photo proof.
	"signer_name" VARCHAR(160),
	-- Object storage key for the signature or photo. The image itself never belongs in the database.
	"storage_key" VARCHAR(400),
	-- WGS84 latitude at capture. The whole evidentiary value of a photo proof is that it was taken at the address.
	"latitude" NUMERIC(9,6),
	-- WGS84 longitude at capture.
	"longitude" NUMERIC(9,6),
	-- Reported GPS accuracy. A proof captured with a 500 metre fix proves considerably less, and a dispute needs to know that.
	"accuracy_metres" SMALLINT,
	-- Handheld that captured it, which is how a pattern of implausible proofs gets traced to one device.
	"device_id" VARCHAR(64),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "proofs_of_delivery" IS 'Evidence that a handover happened, tied to the attempt rather than to the order. Capture time, location and accuracy are stored together because a proof without them is an assertion.';
COMMENT ON COLUMN "proofs_of_delivery"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "proofs_of_delivery"."delivery_attempt_id" IS 'Attempt this proves. Unique, so proof is one-to-one with a successful attempt and cannot be attached retrospectively to a different one.';
COMMENT ON COLUMN "proofs_of_delivery"."proof_type" IS 'signature | photo | pin | id_check | safe_place. The type must satisfy what the order demanded, which is why requires_signature lives on the order.';
COMMENT ON COLUMN "proofs_of_delivery"."captured_at" IS 'Device timestamp of capture, not upload. Handhelds capture offline and sync later, sometimes hours later.';
COMMENT ON COLUMN "proofs_of_delivery"."signer_name" IS 'Name given at handover. Null for a contactless photo proof.';
COMMENT ON COLUMN "proofs_of_delivery"."storage_key" IS 'Object storage key for the signature or photo. The image itself never belongs in the database.';
COMMENT ON COLUMN "proofs_of_delivery"."latitude" IS 'WGS84 latitude at capture. The whole evidentiary value of a photo proof is that it was taken at the address.';
COMMENT ON COLUMN "proofs_of_delivery"."longitude" IS 'WGS84 longitude at capture.';
COMMENT ON COLUMN "proofs_of_delivery"."accuracy_metres" IS 'Reported GPS accuracy. A proof captured with a 500 metre fix proves considerably less, and a dispute needs to know that.';
COMMENT ON COLUMN "proofs_of_delivery"."device_id" IS 'Handheld that captured it, which is how a pattern of implausible proofs gets traced to one device.';

CREATE TABLE IF NOT EXISTS "geofence_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stop whose geofence was crossed.
	"route_stop_id" BIGINT NOT NULL,
	-- enter | exit | dwell. Dwell is emitted when the device stays inside long enough to distinguish a delivery from a van passing through.
	"event_type" VARCHAR(16) NOT NULL,
	-- Device time of the crossing. Devices buffer while out of signal and replay later, so rows arrive out of order and must not be assumed monotonic.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- WGS84 latitude at the crossing.
	"latitude" NUMERIC(9,6) NOT NULL,
	-- WGS84 longitude at the crossing.
	"longitude" NUMERIC(9,6) NOT NULL,
	-- Reported GPS accuracy. A fix worse than the fence radius produces a crossing that never physically happened, which is the main source of false arrivals.
	"accuracy_metres" SMALLINT,
	-- True when this event is the one that set the stop to arrived. At most one per stop; the rest are context.
	"is_auto_arrival" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "geofence_events" IS 'Raw arrival detection, kept apart from the arrival time it produces. Automatic arrival is guesswork over noisy GPS, and when a customer disputes a two-minute visit the underlying crossings are the only way to adjudicate it.';
COMMENT ON COLUMN "geofence_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "geofence_events"."route_stop_id" IS 'Stop whose geofence was crossed.';
COMMENT ON COLUMN "geofence_events"."event_type" IS 'enter | exit | dwell. Dwell is emitted when the device stays inside long enough to distinguish a delivery from a van passing through.';
COMMENT ON COLUMN "geofence_events"."occurred_at" IS 'Device time of the crossing. Devices buffer while out of signal and replay later, so rows arrive out of order and must not be assumed monotonic.';
COMMENT ON COLUMN "geofence_events"."latitude" IS 'WGS84 latitude at the crossing.';
COMMENT ON COLUMN "geofence_events"."longitude" IS 'WGS84 longitude at the crossing.';
COMMENT ON COLUMN "geofence_events"."accuracy_metres" IS 'Reported GPS accuracy. A fix worse than the fence radius produces a crossing that never physically happened, which is the main source of false arrivals.';
COMMENT ON COLUMN "geofence_events"."is_auto_arrival" IS 'True when this event is the one that set the stop to arrived. At most one per stop; the rest are context.';

CREATE INDEX "idx_geofence_stop_time"
ON "geofence_events" ("route_stop_id", "occurred_at");

